using UnityEngine;
namespace ClaudeSFX {
public class SFXDemoController:MonoBehaviour {
 public GameObject[] cars;public AnimatedCarController[] effects;public ProceduralEngineAudio sound;public int CarIndex{get;private set;}public EffectTelemetry Telemetry{get;private set;}public string Label="Idle — simulated telemetry";public bool Automatic=true;float clock;int previous=-1;public int Phase{get;private set;}
 public void SelectCar(int index){CarIndex=index;sound.SetVoice(index);for(int i=0;i<cars.Length;i++){cars[i].SetActive(i==index);if(i!=index)effects[i].Apply(default);}}
 public void Apply(EffectTelemetry state,string label){Telemetry=state;Label=label;sound.Apply(state);effects[CarIndex].Apply(state);}
 public void PhaseState(int phase){Phase=phase;var s=new EffectTelemetry{rpm=900,grounded=true};string label="Idle";switch(phase){case 1:s.rpm=4200;s.load=.8f;label="Engine rev — load/RPM";break;case 2:s.rpm=4500;s.load=.85f;s.turbo=true;s.boostBar=CarIndex==0?.35f:.85f;label="Turbo — boost/load gate";break;case 3:s.rpm=4800;s.load=.65f;s.speed=16;s.slip=.65f;label="Drift — grounded wheel-slip input";break;case 4:s.rpm=4200;s.load=.02f;s.downpipe=true;label="Exhaust — downpipe/lift preview";break;case 5:s.rpm=5200;s.load=.8f;s.supercharger=s.superchargerPreview=true;label="Supercharger — PREVIEW HARDWARE ONLY";break;case 6:s.rpm=4500;s.load=.9f;s.boostBar=.8f;label="Hardware absent — turbo/super muted";break;}Apply(s,label+" | simulated/replayed telemetry");if(phase==4&&previous!=phase)sound.Pop();previous=phase;}
 void Start(){SelectCar(0);PhaseState(0);}
 void Update(){if(Input.GetKeyDown(KeyCode.Tab))SelectCar(1-CarIndex);if(Input.GetKeyDown(KeyCode.Space))Automatic=!Automatic;if(Input.GetKeyDown(KeyCode.T)){Automatic=false;PhaseState(2);}if(Input.GetKeyDown(KeyCode.S)){Automatic=false;PhaseState(5);}if(Input.GetKeyDown(KeyCode.D)){Automatic=false;PhaseState(3);}if(Input.GetKeyDown(KeyCode.P)){Automatic=false;PhaseState(4);sound.Pop();}if(Automatic){clock+=Time.unscaledDeltaTime;int phase=((int)(clock/2))%7;PhaseState(phase);}else effects[CarIndex].Apply(Telemetry);}
 void OnGUI(){GUI.Box(new Rect(16,16,Screen.width-32,110),"HARBOR VALE | SOUND & VISUAL EFFECTS REVIEW");GUI.Label(new Rect(30,43,Screen.width-60,28),(CarIndex==0?"ASTER FINCH":"ASTER APEX")+" | "+Label);GUI.Label(new Rect(30,72,Screen.width-60,40),"Turbo gain "+sound.TurboGain.ToString("F3")+"  |  tire gain "+sound.SquealGain.ToString("F3")+"  |  super gain "+sound.SuperGain.ToString("F3")+"\nStatic visual demo; no racing, upgrades, mileage or vehicle physics are simulated here.");GUI.Box(new Rect(16,Screen.height-66,Screen.width-32,50),"TAB car | SPACE auto/pause | T turbo | D drift | P pop | S supercharger preview");}
}
}
